/**
 * design-system — builds /design-system/ and its story pages in a pass of their own, so that adding
 * them leaves every real page's built output byte-identical. GENERATED by the blinkpages-migrate
 * skill (templates/design-system/integration.mjs.template): don't edit it here. Astro ≥ 7.
 *
 * WHY. Astro (Rolldown) puts each module in a chunk keyed by the set of pages that reach it, and
 * orders a chunk's modules by the order they are first reached. The story route imports every
 * component and the layout's stylesheets, so built beside the real pages it gives those modules a
 * new importer: their CSS leaves the chunks it shared, and every page's inline <style>s (or linked
 * stylesheet names) change, though no rule does. On the first seven sites moved to /design-system/,
 * every real page changed (cascade-partners: 431 pages). An import shape that happens to keep the
 * grouping still depends on the order Rolldown reaches modules, so none is a guarantee
 * (style-library.md §3). The person's rule, 2026-11-03: adding the page changes no real page.
 *
 * HOW.
 *   - `astro build` (the site's own build): src/pages/design-system.astro and
 *     src/pages/design-system/** load as empty stubs that import nothing but Astro itself. No CSS
 *     module gains an importer, so every chunk, every inline <style> and every file name is what it
 *     would be with no design-system page at all.
 *   - Then, after every other integration has finished with dist/, it runs `astro build` once more,
 *     into a fresh temporary directory, with every OTHER page a stub, and copies in the
 *     design-system pages and the _astro files they add. It never overwrites a file the site's own
 *     build wrote. Same config, same integrations, same compiler (the editor's source annotation
 *     included): the pages are what they would be in one build, minus the side effect.
 *   - `astro dev` serves everything together, as usual: dev CSS is not chunked.
 *
 * The story route reads `virtual:design-system/story`: the layout most native pages use (imported,
 * never rendered, for its stylesheets and its chrome's), every component, and
 * src/components/design-system/StoryDefs.astro when the site has one. Only this integration
 * provides it, so a site that forgot to register it fails its build instead of shipping real pages
 * with changed CSS. The book page carries <meta name="design-system-build" content="pass">, which
 * gate-style-library.mjs checks.
 *
 * Register it in astro.config.mjs (`designSystem()` in integrations). Its copy step is appended
 * after every integration the config lists, wherever it sits.
 *   designSystem({ layout: "src/layouts/Base.astro" })  — name the layout instead of detecting it.
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const ROUTE = "design-system";
const PASS_ENV = "BLINK_DESIGN_SYSTEM_PASS";
const STORY = "virtual:design-system/story";
const BUILD = "virtual:design-system/build";
const ENDPOINT = /\.(m?[jt]s)$/;

/** A page module that renders nothing and imports nothing of the site's. */
function stubOf(file) {
  const dynamic = /\[/.test(path.basename(file)) || /\[/.test(path.dirname(file));
  if (file.endsWith(".astro")) return dynamic ? "---\nexport function getStaticPaths() { return []; }\n---\n" : "";
  if (ENDPOINT.test(file)) return `${dynamic ? "export function getStaticPaths() { return []; }\n" : ""}export function GET() { return new Response(""); }\n`;
  return null; // .md, .mdx, .html pages build as they are
}

const posix = (p) => p.split(path.sep).join("/");

/** The layout the most native pages import (the site's own pages only), as a root-relative path. */
export function mainLayout(root, srcDir) {
  const pages = path.join(srcDir, "pages"), layouts = path.join(srcDir, "layouts") + path.sep;
  const count = new Map();
  const walk = (dir) => {
    if (!fs.existsSync(dir)) return;
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, e.name);
      if (dir === pages && (e.name === `${ROUTE}.astro` || (e.isDirectory() && e.name === ROUTE))) continue;
      if (e.isDirectory()) { walk(full); continue; }
      if (!/\.(astro|mdx?)$/.test(e.name)) continue;
      const src = fs.readFileSync(full, "utf8");
      const specs = [...src.matchAll(/(?:from|import)\s+["']([^"']+\.astro)["']/g)].map((m) => m[1]);
      const md = src.match(/^---\r?\n[\s\S]*?^layout:\s*["']?([^"'\r\n]+)/m);
      if (md) specs.push(md[1].trim());
      for (const s of new Set(specs)) {
        const abs = s.startsWith(".") ? path.resolve(dir, s)
          : /^[@~]\//.test(s) ? path.join(srcDir, s.slice(2))
          : s.startsWith("@layouts/") ? path.join(srcDir, "layouts", s.slice(9))
          : s.startsWith("/") ? path.join(root, s) : null;
        if (abs && abs.startsWith(layouts) && fs.existsSync(abs)) count.set(abs, (count.get(abs) ?? 0) + 1);
      }
    }
  };
  walk(pages);
  const best = [...count].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0];
  return best ? `/${posix(path.relative(root, best[0]))}` : undefined;
}

/** virtual:design-system/story — what every story page carries. */
function storyModule(root, srcDir, layout) {
  const src = `/${posix(path.relative(root, srcDir))}`;
  const lay = layout ? `/${posix(path.relative(root, path.resolve(root, layout.replace(/^\//, ""))))}` : mainLayout(root, srcDir);
  /* no layout to read: the stylesheets the scaffold's layouts import */
  const sheets = lay ? `import ${JSON.stringify(lay)};\n`
    : `import.meta.glob(["${src}/styles/**/fonts*.css", "${src}/styles/tokens.css", "${src}/styles/global.css"], { eager: true });\n`;
  return `// generated by src/integrations/design-system.mjs
// the layout's stylesheets (and its chrome's) first, as on a real page: imported, never rendered
${sheets}export const layout = ${JSON.stringify(lay ?? null)};
export const components = import.meta.glob(["${src}/components/**/*.astro", "!${src}/components/${ROUTE}/**"], { eager: true });
/** a component by its path under src/components/ (stories.ts \`component\`) */
export const component = (rel) => components[\`${src}/components/\${rel}\`]?.default;
const defs = import.meta.glob("${src}/components/${ROUTE}/StoryDefs.astro", { eager: true });
export const StoryDefs = Object.values(defs)[0]?.default;
`;
}

/** The pass's assets its own pages use: named in their HTML, or in a script or stylesheet those use.
    The pass stubs every real page, so an image a story's data imports but no story draws is never
    optimized, and Astro keeps its full original (31 MB of unused covers on a book site, 2026-11-25). */
export function usedAssets(assets, texts, read) {
  const left = new Map(assets.map((rel) => [rel, [...new Set([path.posix.basename(rel), encodeURI(path.posix.basename(rel))])]]));
  const used = [], queue = [...texts];
  while (queue.length) {
    const text = queue.pop();
    for (const [rel, names] of left) if (names.some((n) => text.includes(n))) {
      left.delete(rel); used.push(rel);
      if (/\.(m?js|css|json|svg)$/.test(rel)) queue.push(read(rel));
    }
  }
  return used;
}

export default function designSystem({ layout } = {}) {
  const pass = process.env[PASS_ENV] === "1";
  let root, srcDir, pagesDir, assetsDir;
  const ownFile = (file) => file === path.join(pagesDir, `${ROUTE}.astro`) || file.startsWith(path.join(pagesDir, ROUTE) + path.sep);
  /* not a route: a _partial under src/pages */
  const route = (file) => !posix(path.relative(pagesDir, file)).split("/").some((s) => s.startsWith("_"));

  const plugin = (mode) => ({
    name: "design-system",
    enforce: "pre",
    resolveId(id) {
      if (id === STORY || id === BUILD) return `\0${id}`;
      return null;
    },
    load(id) {
      if (id === `\0${BUILD}`) return `export const built = ${JSON.stringify(mode)};\n`;
      if (id === `\0${STORY}`) {
        if (mode === "main") this.error("design-system: the story route reached the site's own build. It must load as a stub there (src/integrations/design-system.mjs).");
        return storyModule(root, srcDir, layout);
      }
      if (mode === "dev" || id.startsWith("\0") || id.includes("?")) return null;
      const file = path.normalize(id);
      if (!file.startsWith(pagesDir + path.sep) || !route(file)) return null;
      /* the site's own build stubs the design-system routes; the pass stubs every other page */
      if (mode === "main" ? !ownFile(file) : ownFile(file)) return null;
      return stubOf(file);
    },
  });

  /* after every other integration's astro:build:done: the pass, then the copy */
  const copyStep = {
    name: "design-system:pass",
    hooks: {
      "astro:build:done": ({ dir, logger }) => {
        const out = fileURLToPath(dir);
        if (!fs.existsSync(path.join(pagesDir, `${ROUTE}.astro`)) && !fs.existsSync(path.join(pagesDir, ROUTE))) return;
        /* a fresh directory per build, outside the project: worktrees that share one symlinked
           node_modules each built into node_modules/.cache and clobbered one another (2026-11-03) */
        const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "design-system-pass-"));
        const astroBin = path.join(path.dirname(createRequire(path.join(root, "package.json")).resolve("astro/package.json")), "bin", "astro.mjs");
        /* the site's own `astro build` flags, minus its outDir */
        const argv = process.argv.slice(2);
        const flags = argv[0] === "build" ? argv.slice(1).filter((a, i, all) => !/^--outDir(=|$)/.test(a) && !/^--outDir$/.test(all[i - 1] ?? "")) : [];
        const t0 = Date.now();
        const r = spawnSync(process.execPath, [astroBin, "build", ...flags, "--outDir", scratch], {
          cwd: root, env: { ...process.env, [PASS_ENV]: "1" }, encoding: "utf8", maxBuffer: 256 * 1024 * 1024,
        });
        if (r.status !== 0) {
          process.stderr.write(`${r.stdout ?? ""}${r.stderr ?? ""}`.split("\n").slice(-60).join("\n"));
          fs.rmSync(scratch, { recursive: true, force: true });
          throw new Error(`design-system: the separate pass (astro build with ${PASS_ENV}=1) failed${r.error ? `: ${r.error.message}` : ""}`);
        }
        /* the design-system pages replace the stubs the site's own build wrote */
        for (const name of [ROUTE, `${ROUTE}.html`]) {
          const from = path.join(scratch, name), to = path.join(out, name);
          if (!fs.existsSync(from)) continue;
          fs.rmSync(to, { recursive: true, force: true });
          fs.cpSync(from, to, { recursive: true });
        }
        const count = (d) => (fs.existsSync(d) ? fs.readdirSync(d, { recursive: true }).filter((f) => /\.html$/.test(f)).length : 0);
        const pages = count(path.join(out, ROUTE)) + (fs.existsSync(path.join(out, `${ROUTE}.html`)) ? 1 : 0);
        /* the assets they use (scripts, images), never one the site's own build wrote */
        let added = 0;
        const from = path.join(scratch, assetsDir), to = path.join(out, assetsDir);
        if (fs.existsSync(from)) {
          const files = (d) => (fs.existsSync(d) ? fs.readdirSync(d, { recursive: true, withFileTypes: true }).filter((e) => e.isFile()).map((e) => path.join(e.parentPath, e.name)) : []);
          const html = [...files(path.join(scratch, ROUTE)), path.join(scratch, `${ROUTE}.html`)].filter((f) => /\.(html|m?js|css|json)$/.test(f) && fs.existsSync(f));
          const read = (rel) => fs.readFileSync(path.join(from, rel), "utf8");
          for (const rel of usedAssets(files(from).map((f) => posix(path.relative(from, f))), html.map((f) => fs.readFileSync(f, "utf8")), read)) {
            const t = path.join(to, rel);
            if (fs.existsSync(t)) continue;
            fs.mkdirSync(path.dirname(t), { recursive: true }); fs.copyFileSync(path.join(from, rel), t); added++;
          }
        }
        fs.rmSync(scratch, { recursive: true, force: true });
        logger.info(`${pages} page(s) built in a separate pass (${((Date.now() - t0) / 1000).toFixed(1)}s), ${added} asset(s) added; the site's own pages untouched`);
      },
    },
  };

  return {
    name: "design-system",
    hooks: {
      "astro:config:setup": ({ command, config, updateConfig }) => {
        root = fileURLToPath(config.root);
        /* the pass needs Astro 7: on 5 or 6 the build died on a missing astro/bin/astro.mjs, which said
           nothing about why (adaptedgrowth, helloseo, 2026-11-03) */
        const astroVersion = JSON.parse(fs.readFileSync(createRequire(path.join(root, "package.json")).resolve("astro/package.json"), "utf8")).version;
        if (Number(String(astroVersion).split(".")[0]) < 7) throw new Error(`design-system: this site is on Astro ${astroVersion}, and the design-system page needs Astro 7. Upgrade first (astro-upgrade.md), or take designSystem() out of astro.config.mjs until then.`);
        srcDir = fileURLToPath(config.srcDir);
        pagesDir = path.join(srcDir, "pages");
        assetsDir = config.build.assets || "_astro";
        const mode = command !== "build" ? "dev" : pass ? "pass" : "main";
        updateConfig({ vite: { plugins: [plugin(mode)] } });
        /* appended: Astro runs integrations in order, so this one's build:done is the last */
        if (mode === "main") updateConfig({ integrations: [copyStep] });
      },
      "astro:config:done": ({ injectTypes }) => {
        injectTypes({
          filename: "virtual.d.ts",
          content: `declare module "${STORY}" {\n  export const layout: string | null;\n  export const components: Record<string, { default: any }>;\n  export function component(rel: string): any;\n  export const StoryDefs: any;\n}\ndeclare module "${BUILD}" {\n  /** "pass" in the separate design-system pass, "dev" under astro dev */\n  export const built: "pass" | "main" | "dev";\n}\n`,
        });
      },
    },
  };
}
